      workout: { premade_id: 'morning-energizer', motivational_tip: 'The same time, the same workout, the same discipline — every day. Routine is your armor.', coach_note: 'Consistency is your new superpower. Show up at the same time every day.' },
      nutrition: { focus: 'Meal timing', meal_theme: 'Structure and consistency', plan: 'Eat at the same times every day this week. Breakfast within 1 hour of waking, lunch midday, dinner early evening. Consistent meal timing stabilizes blood sugar and reduces cravings.', tip: 'Set alarms for meals if you need to. Treat eating like medicine — non-negotiable.', recipe_search: 'structured meal plan routine' },
      affirmation: 'I am building a daily structure that holds me. My routine is my armor, and consistency is my weapon.',
